insert into series (id, slug, name, year, timeline, format, color, synopsis, image_url) values
  (1, 'mobile-suit-gundam', 'Mobile Suit Gundam', 1979, 'Universal Century 0079', 'TV', '#e63946', 'Perang Satu Tahun antara Federasi Bumi dan Kerajaan Zeon. Amuro Ray, remaja yang tinggal di koloni luar angkasa, terseret ke medan perang ketika ia menaiki prototipe RX-78-2 Gundam, dan perlahan berubah dari anak biasa menjadi pilot ulung. Serial yang melahirkan genre real robot.', null),
  (2, 'zeta-gundam', 'Mobile Suit Zeta Gundam', 1985, 'Universal Century 0087', 'TV', '#f4a261', 'Tujuh tahun setelah Perang Satu Tahun, Federasi dikuasai pasukan elit Titans. Kamille Bidan bergabung dengan AEUG untuk melawan mereka dan menjadi pilot Zeta Gundam, mobile suit yang bisa berubah menjadi pesawat tempur.', null),
  (3, 'gundam-zz', 'Mobile Suit Gundam ZZ', 1986, 'Universal Century 0088', 'TV', '#ffd166', 'Lanjutan Zeta Gundam dengan nuansa lebih ringan. Judau Ashta, pemuda pemulung dari koloni Shangri-La, menjadi pilot ZZ Gundam saat Neo Zeon yang dipimpin Haman Karn bangkit memperebutkan kekuasaan.', null),
  (4, 'chars-counterattack', 'Mobile Suit Gundam: Char''s Counterattack', 1988, 'Universal Century 0093', 'Film', '#c1121f', 'Film layar lebar yang menutup rivalitas Amuro Ray dan Char Aznable. Char memimpin pasukan Neo Zeon dan berencana menjatuhkan asteroid Axis ke Bumi, sementara Amuro berusaha menghentikannya dengan ν Gundam.', null),
  (5, 'gundam-unicorn', 'Mobile Suit Gundam Unicorn', 2010, 'Universal Century 0096', 'OVA', '#7b9ea8', 'Banagher Links, siswa biasa, menemukan Unicorn Gundam dan terlibat dalam perburuan "Laplace''s Box", kunci rahasia yang bisa mengguncang tatanan politik Federasi dan sisa-sisa Zeon.', null),
  (6, 'gundam-wing', 'Mobile Suit Gundam Wing', 1995, 'After Colony 195', 'TV', '#4cc9f0', 'Lima pilot muda dari koloni luar angkasa dikirim ke Bumi dengan Gundam masing-masing untuk melawan Aliansi Bumi dan organisasi OZ. Heero Yuy, Duo Maxwell, Trowa Barton, Quatre Raberba Winner, dan Chang Wufei punya cara berbeda memaknai perang.', null),
  (7, 'g-gundam', 'Mobile Fighter G Gundam', 1994, 'Future Century', 'TV', '#f77f00', 'Setiap koloni mengirim satu Gundam Fighter ke turnamen Gundam Fight untuk menentukan penguasa koloni berikutnya. Domon Kasshu, pilot Shining Gundam dari Neo Japan, bertarung sambil mengejar kakaknya yang menghilang. Gayanya lebih mirip seni bela diri ketimbang perang.', null),
  (8, 'gundam-seed', 'Mobile Suit Gundam SEED', 2002, 'Cosmic Era 71', 'TV', '#3a86ff', 'Konflik antara Natural dan Coordinator, manusia hasil rekayasa genetika, meledak menjadi perang ORB, Aliansi Bumi, dan ZAFT. Kira Yamato, Coordinator yang tinggal di koloni netral, terpaksa menjadi pilot Strike Gundam dan harus berhadapan dengan sahabat lamanya, Athrun Zala.', null),
  (9, 'gundam-00', 'Mobile Suit Gundam 00', 2007, 'Anno Domini 2307', 'TV', '#2ec4b6', 'Organisasi bersenjata Celestial Being berambisi menghapus perang dengan intervensi bersenjata memakai Gundam bertenaga GN Drive. Setsuna F. Seiei, pilot Gundam Exia, mempertaruhkan hidupnya untuk idealisme itu di tengah dunia yang terbagi tiga blok kekuatan.', null),
  (10, 'iron-blooded-orphans', 'Mobile Suit Gundam: Iron-Blooded Orphans', 2015, 'Post Disaster 323', 'TV', '#9d4edd', 'Kelompok tentara anak Tekkadan, dipimpin Orga Itsuka, memberontak melawan perusahaan yang memperbudak mereka. Mikazuki Augus mengendalikan Gundam Barbatos, mobile frame kuno berusia ratusan tahun, dalam kisah yang suram dan penuh pengorbanan.', null),
  (11, 'witch-from-mercury', 'Mobile Suit Gundam: The Witch from Mercury', 2022, 'Ad Stella', 'TV', '#e0aaff', 'Suletta Mercury, siswi pindahan dari Merkurius, mendaftar ke Asticassia School of Technology dengan Gundam Aerial. Di sekolah yang semua urusannya diselesaikan lewat duel mobile suit, ia terlibat bersama Miorine Rembran dalam intrik perusahaan dan rahasia di balik teknologi Gundam.', null),
  (12, 'war-in-the-pocket', 'Mobile Suit Gundam 0080: War in the Pocket', 1989, 'Universal Century 0079', 'OVA', '#8ab17d', 'Di akhir Perang Satu Tahun, Alfred Izuruha, anak laki-laki di koloni netral Side 6, berteman dengan Bernard "Bernie" Wiseman, pilot muda Zeon yang ditugaskan menghancurkan Gundam NT-1 milik Federasi sebelum dikirim. Kisah perang dari sudut pandang seorang anak.', null),
  (13, 'stardust-memory', 'Mobile Suit Gundam 0083: Stardust Memory', 1991, 'Universal Century 0083', 'OVA', '#e76f51', 'Anavel Gato dari Armada Delaz mencuri Gundam GP02A yang membawa hulu ledak nuklir dari pangkalan Federasi. Kou Uraki, pilot uji Gundam GP01, mengejarnya dalam rangkaian peristiwa yang dikenal sebagai Operasi Stardust.', null),
  (14, 'gundam-f91', 'Mobile Suit Gundam F91', 1991, 'Universal Century 0123', 'Film', '#577590', 'Tiga puluh tahun setelah Char''s Counterattack, Crossbone Vanguard menyerbu koloni Frontier IV. Seabook Arno, pelajar yang ikut mengungsi, menjadi pilot Gundam F91 sambil mencari teman masa kecilnya, Cecily Fairchild, yang ternyata keturunan keluarga Ronah.', null),
  (15, 'victory-gundam', 'Mobile Suit Victory Gundam', 1993, 'Universal Century 0153', 'TV', '#43aa8b', 'Saat Federasi Bumi melemah, kekaisaran Zanscare menguasai luar angkasa. Uso Ewin, anak berusia tiga belas tahun, bergabung dengan kelompok perlawanan League Militaire sebagai pilot Victory Gundam. Dikenal sebagai salah satu serial Gundam paling kelam.', null),
  (16, 'after-war-gundam-x', 'After War Gundam X', 1996, 'After War 0015', 'TV', '#90be6d', 'Lima belas tahun setelah perang yang menghancurkan Bumi, Garrod Ran, remaja pemulung, menemukan Gundam X dan bertemu Tiffa Adill, gadis Newtype. Ia bergabung dengan kapal Freeden dan terseret dalam perebutan para Newtype.', null),
  (17, 'turn-a-gundam', 'Turn A Gundam', 1999, 'Correct Century 2343', 'TV', '#c9ada7', 'Ribuan tahun setelah era-era perang sebelumnya, manusia di Bumi hidup dengan teknologi setara awal abad ke-20. Loran Cehack, pemuda dari Bulan, menemukan Turn A Gundam kuno yang tersembunyi di dalam patung dan terjebak di antara konflik Bumi dan bangsa Moonrace.', null),
  (18, 'gundam-seed-destiny', 'Mobile Suit Gundam SEED Destiny', 2004, 'Cosmic Era 73', 'TV', '#ef476f', 'Dua tahun setelah Gundam SEED, perang antara ZAFT dan Aliansi Bumi kembali pecah. Shinn Asuka, pilot ZAFT yang kehilangan keluarganya dalam perang sebelumnya, berhadapan dengan Kira Yamato dan Athrun Zala yang kini berada di pihak berbeda.', null),
  (19, 'gundam-age', 'Mobile Suit Gundam AGE', 2011, 'Advanced Generation 115', 'TV', '#06d6a0', 'Kisah tiga generasi keluarga Asuno (Flit, Asemu, dan Kio) dalam perang panjang melawan musuh misterius yang kemudian dikenal sebagai Vagan. Dimulai dari Flit Asuno yang membangun Gundam AGE-1 dengan sistem AGE yang terus berevolusi.', null),
  (20, 'gundam-build-fighters', 'Gundam Build Fighters', 2013, 'Dunia modern (Gunpla Battle)', 'TV', '#ffbe0b', 'Di dunia ini model plastik Gundam (Gunpla) bisa dipertarungkan lewat sistem Plavsky Particle. Sei Iori, pembuat Gunpla berbakat, berpasangan dengan Reiji yang jago bertarung untuk menjuarai Gunpla Battle World Championship.', null),
  (21, 'gundam-hathaway', 'Mobile Suit Gundam: Hathaway', 2021, 'Universal Century 0105', 'Film', '#6d597a', 'Dua belas tahun setelah Char''s Counterattack, Hathaway Noa diam-diam memimpin organisasi anti-Federasi Mafty yang menentang kebijakan Federasi memaksa penduduk pindah ke luar angkasa. Dalam misinya ia mengemudikan Xi Gundam.', null)
insert into mobile_suits (id, name, model_number, series_id, pilot, faction, unit_type, height_m, weight_t, armaments, description, image_url) values
  (1, 'Gundam', 'RX-78-2', 1, 'Amuro Ray', 'Earth Federation', 'Prototipe serbaguna', 18, 43.4, array['Beam Rifle', 'Beam Saber', '60mm Vulcan', 'Hyper Bazooka', 'Shield'], 'Mobile suit prototipe Federasi Bumi dari Proyek V. Armor Luna Titanium dan persenjataan beam membuatnya jauh melampaui Zaku. Di tangan Amuro Ray, unit ini menjadi simbol seluruh franchise.', 'https://static.wikia.nocookie.net/gundam/images/3/36/01._RX-78-2_Gundam.jpg/revision/latest/scale-to-width-down/390?cb=20170821232511'),
  (2, 'Guncannon', 'RX-77-2', 1, 'Kai Shiden', 'Earth Federation', 'Dukungan jarak jauh', 17.5, 53.2, array['240mm Cannon', 'Beam Rifle'], 'Mobile suit pendukung artileri dari Proyek V dengan dua meriam di pundak. Dalam serial ini dikemudikan Kai Shiden dan bertugas menembak dari belakang saat Gundam maju.', 'https://static.wikia.nocookie.net/gundam/images/e/eb/Rx-77-2.jpg/revision/latest/scale-to-width-down/428?cb=20201105132335'),
  (3, 'Zaku II Commander Type (Char Custom)', 'MS-06S', 1, 'Char Aznable', 'Principality of Zeon', 'Unit komandan', 17.5, 56.2, array['Zaku Machine Gun', 'Heat Hawk', 'Zaku Bazooka'], 'Zaku II versi komandan yang dicat merah dan dikenal sebagai "Komet Merah". Mobilitasnya jauh di atas Zaku biasa dan menjadi ikon rival Amuro, Char Aznable.', 'https://static.wikia.nocookie.net/gundam/images/9/91/Ms-06s-standard.jpg/revision/latest/scale-to-width-down/366?cb=20130101071828'),
  (4, 'Gouf', 'MS-07B', 1, 'Ramba Ral', 'Principality of Zeon', 'Pertempuran darat', 18.7, 58.5, array['Heat Rod', 'Finger Vulcan', 'Shield with Machine Gun'], 'Mobile suit tempur darat Zeon yang lebih gesit dari Zaku. Terkenal dipakai Ramba Ral, ace Zeon yang dihormati lawan maupun kawan.', 'https://static.wikia.nocookie.net/gundam/images/d/d1/Ms-07b_1.jpg/revision/latest/scale-to-width-down/385?cb=20201101133303'),
  (5, 'Dom', 'MS-09', 1, 'Black Tri-Stars', 'Principality of Zeon', 'Serangan cepat', 18.6, 62.6, array['Giant Bazooka', 'Heat Saber'], 'Mobile suit bertubuh tambun dengan pendorong hover. Meski tampak berat, Dom sangat lincah di darat dan terkenal lewat formasi Jet Stream Attack milik Black Tri-Stars.', 'https://static.wikia.nocookie.net/gundam/images/3/3d/Ms-09R.jpg/revision/latest/scale-to-width-down/466?cb=20201106104407'),
  (6, 'Zeta Gundam', 'MSZ-006', 2, 'Kamille Bidan', 'AEUG', 'Transformable', 19.85, 28.7, array['Beam Rifle', 'Beam Saber', 'Hyper Mega Launcher'], 'Gundam transformable pertama yang berubah menjadi mode Waverider untuk penerbangan dan masuk atmosfer. Dirancang oleh Anaheim Electronics dan dikemudikan Kamille Bidan.', 'https://static.wikia.nocookie.net/gundam/images/d/d9/Zeta_Gundam_Front_HD.png/revision/latest/scale-to-width-down/402?cb=20240911030026'),
  (7, 'Hyaku Shiki', 'MSN-00100', 2, 'Quattro Bajeena (Char Aznable)', 'AEUG', 'Unit komandan', 19.5, null, array['Beam Rifle', 'Beam Saber', 'Clay Bazooka'], 'Mobile suit berwarna emas yang dipakai Quattro Bajeena, identitas baru Char Aznable. Tampilan emasnya langsung mudah dikenali di medan perang.', 'https://static.wikia.nocookie.net/gundam/images/8/8c/Msn-00100.jpg/revision/latest/scale-to-width-down/323?cb=20201007114351'),
  (8, 'The O', 'PMX-003', 2, 'Paptimus Scirocco', 'Titans', 'Unit komandan', 28, null, array['Beam Rifle', 'Beam Saber', 'Sub-arms'], 'Mobile suit raksasa milik Paptimus Scirocco dari Titans. Dilengkapi lengan tambahan di punggung yang bisa memegang senjata, membuatnya terlihat mengintimidasi.', 'https://static.wikia.nocookie.net/gundam/images/8/85/Pmx-003.jpg/revision/latest/scale-to-width-down/455?cb=20121115202935'),
  (9, 'ZZ Gundam', 'MSZ-010', 3, 'Judau Ashta', 'AEUG', 'Combining', null, null, array['Double Beam Rifle', 'Hi-Mega Cannon', 'Beam Saber'], 'Gundam yang tersusun dari beberapa bagian yang bisa dipisah dan digabung kembali. Senjata utamanya, Hi-Mega Cannon di dahi, punya daya hancur sangat besar.', 'https://static.wikia.nocookie.net/gundam/images/8/81/ZZ_Gundam_Front_HD.png/revision/latest/scale-to-width-down/435?cb=20260809140233'),
  (10, 'Qubeley', 'AMX-004', 3, 'Haman Karn', 'Neo Zeon', 'Newtype khusus', null, null, array['Funnel', 'Beam Saber'], 'Mobile suit khusus Newtype Neo Zeon dengan Funnel kendali pikiran. Haman Karn memakainya sebagai senjata utama dalam perebutan kekuasaan di era ZZ.', 'https://static.wikia.nocookie.net/gundam/images/5/53/Amx-004.jpg/revision/latest/scale-to-width-down/640?cb=20180630133743'),
  (11, 'ν Gundam (Nu Gundam)', 'RX-93', 4, 'Amuro Ray', 'Earth Federation', 'Newtype khusus', 22, 28.6, array['Fin Funnel', 'Beam Rifle', 'Beam Saber', 'Hyper Bazooka'], 'Gundam rancangan Amuro Ray sendiri dengan sistem Fin Funnel yang dikendalikan lewat pikiran. Ia menjadi lawan utama Sazabi dalam duel penutup rivalitas Amuro dan Char.', 'https://static.wikia.nocookie.net/gundam/images/8/8c/Rx-93.jpg/revision/latest/scale-to-width-down/349?cb=20201101140124'),
  (12, 'Sazabi', 'MSN-04', 4, 'Char Aznable', 'Neo Zeon', 'Newtype khusus', 22, null, array['Funnel', 'Beam Shot Rifle', 'Beam Tomahawk'], 'Mobile suit merah milik Char yang menjadi pasangan sebanding ν Gundam. Memakai psycho-frame dan dipersenjatai Funnel di punggung, dirancang khusus untuk pilot Newtype.', 'https://static.wikia.nocookie.net/gundam/images/b/b8/MSN-04_Sazabi_-_Front.png/revision/latest/scale-to-width-down/470?cb=20171001171810'),
  (13, 'Unicorn Gundam', 'RX-0', 5, 'Banagher Links', 'Earth Federation', 'Transformable (NT-D)', 19.7, 23.7, array['Beam Magnum', 'Beam Saber', 'Shield'], 'Gundam dengan dua wujud: Unicorn Mode dengan satu tanduk, dan Destroy Mode dengan sistem NT-D ketika tanduknya terbelah menjadi V-fin dan armornya terbuka memperlihatkan psycho-frame merah.', 'https://static.wikia.nocookie.net/gundam/images/b/b2/Unicorn_Gundam_Unicorn_Mode_front.png/revision/latest/scale-to-width-down/365?cb=20260603135516'),
  (14, 'Sinanju', 'MSN-06S', 5, 'Full Frontal', 'Neo Zeon (Sleeves)', 'Newtype khusus', null, null, array['Beam Saber', 'Beam Rifle', 'Beam Axe'], 'Mobile suit merah-kuning milik Full Frontal, pemimpin Sleeves. Dibangun sebagai penerus Sazabi dan menjadi lawan utama Unicorn.', 'https://static.wikia.nocookie.net/gundam/images/b/bc/Msn-06s.jpg/revision/latest/scale-to-width-down/476?cb=20160225053012'),
  (15, 'Wing Gundam', 'XXXG-01W', 6, 'Heero Yuy', 'Koloni (Operation Meteor)', 'Transformable', 16.3, 7.4, array['Buster Rifle', 'Beam Saber', 'Machine Cannon'], 'Gundam utama Heero Yuy yang bisa berubah menjadi mode burung (bird mode). Terbuat dari Gundanium Alloy yang tahan terhadap hampir semua serangan konvensional.', 'https://static.wikia.nocookie.net/gundam/images/8/8b/XXXG-01W_Wing_Gundam_TV_-_Front.png/revision/latest/scale-to-width-down/629?cb=20260930171614'),
  (16, 'Gundam Deathscythe', 'XXXG-01D', 6, 'Duo Maxwell', 'Koloni (Operation Meteor)', 'Infiltrasi dan jarak dekat', null, null, array['Beam Scythe', 'Buster Shield', 'Active Cloak'], 'Gundam hitam Duo Maxwell dengan sabit beam raksasa. Dilengkapi Active Cloak yang membuatnya sulit terdeteksi dan sangat cocok untuk serangan mendadak.', 'https://static.wikia.nocookie.net/gundam/images/4/4a/Gundam_Deathscythe_Front_%28Official%29.png/revision/latest/scale-to-width-down/447?cb=20251010004851'),
  (17, 'Wing Gundam Zero', 'XXXG-00W0', 6, 'Heero Yuy', 'Koloni (Operation Meteor)', 'Transformable (Zero System)', null, null, array['Twin Buster Rifle', 'Beam Saber', 'Machine Cannon'], 'Wing Gundam versi awal dengan Zero System yang menampilkan prediksi pertempuran langsung ke otak pilot. Terkenal bersayap malaikat yang megah dan Twin Buster Rifle yang mematikan.', 'https://static.wikia.nocookie.net/gundam/images/5/59/Wing_Zero_TV_Front_%28Official%29.png/revision/latest/scale-to-width-down/489?cb=20251010041724'),
  (18, 'Shining Gundam', 'GF13-017NJ', 7, 'Domon Kasshu', 'Neo Japan', 'Mobile Fighter', null, null, array['Shining Finger', 'Beam Saber'], 'Mobile Fighter wakil Neo Japan di Gundam Fight ke-13. Bergerak mengikuti gerakan pilotnya lewat sistem Mobile Trace, dengan jurus utama Shining Finger.', 'https://static.wikia.nocookie.net/gundam/images/2/26/GF13-017NJ_Shining_Gundam_Normal_Front.png/revision/latest/scale-to-width-down/405?cb=20251012212555'),
  (19, 'God Gundam', 'GF13-017NJII', 7, 'Domon Kasshu', 'Neo Japan', 'Mobile Fighter', null, null, array['God Finger', 'Ishin Denshin'], 'Evolusi Shining Gundam yang dipakai Domon Kasshu di fase akhir turnamen. Jurus andalannya adalah God Finger, serta teknik Ishin Denshin saat semangat pilotnya membara.', 'https://static.wikia.nocookie.net/gundam/images/c/c9/God_Gundam_Front_%28transparent%29.png/revision/latest/scale-to-width-down/412?cb=20251012212727'),
  (20, 'Strike Gundam', 'GAT-X105', 8, 'Kira Yamato', 'Earth Alliance', 'Prototipe modular', 17.72, 64.8, array['Beam Rifle', 'Beam Saber', 'Armor Schneider', 'IWSP Striker Pack'], 'Prototipe Earth Alliance dengan sistem Striker Pack yang dapat ditukar sesuai misi. Dikemudikan Kira Yamato yang mengoptimalkan OS-nya langsung di tengah pertempuran.', 'https://static.wikia.nocookie.net/gundam/images/e/ea/Strike_gundam_front_lineart_color.png/revision/latest/scale-to-width-down/346?cb=20251012205232'),
  (21, 'Freedom Gundam', 'ZGMF-X10A', 8, 'Kira Yamato', 'ZAFT (Three Ships Alliance)', 'Prototipe nuklir', 18.03, 71.5, array['Beam Rifle', 'Beam Saber', 'Rail Gun', 'Full Burst Mode'], 'Gundam bertenaga reaktor nuklir yang dikembangkan ZAFT lalu direbut Three Ships Alliance. Sayap lebarnya menjadi ciri khas, dan mode Full Burst-nya menembakkan seluruh senjata sekaligus.', 'https://static.wikia.nocookie.net/gundam/images/d/d1/Freedom_gundam_front_lineart_color.png/revision/latest/scale-to-width-down/462?cb=20260103063443'),
  (22, 'Justice Gundam', 'ZGMF-X09A', 8, 'Athrun Zala', 'ZAFT', 'Prototipe nuklir', 18.03, 79.17, array['Beam Rifle', 'Beam Saber', 'Fatum-00'], 'Gundam kembaran Freedom milik Athrun Zala. Sistem Fatum-00 di punggungnya bisa dilepas dan dikendalikan terpisah dari bodi utama.', 'https://static.wikia.nocookie.net/gundam/images/b/bc/Justice_gundam_front_lineart_color.png/revision/latest/scale-to-width-down/438?cb=20251011054614'),
  (23, 'Gundam Exia', 'GN-001', 9, 'Setsuna F. Seiei', 'Celestial Being', 'Jarak dekat', 18.3, 57.5, array['GN Sword', 'GN Long Blade', 'GN Short Blade', 'GN Beam Dagger'], 'Gundam generasi pertama Celestial Being yang mengandalkan GN Drive. Kekuatan jarak dekatnya sangat tinggi dan mode Trans-Am menaikkan seluruh performanya dalam waktu singkat.', 'https://static.wikia.nocookie.net/gundam/images/d/d9/GN-001_%28Front%29.png/revision/latest/scale-to-width-down/324?cb=20210804123915'),
  (24, '00 Gundam', 'GN-0000', 9, 'Setsuna F. Seiei', 'Celestial Being', 'Twin Drive', 18.3, null, array['GN Sword', 'GN Beam Saber'], 'Gundam dengan dua GN Drive (Twin Drive) yang menghasilkan energi sangat besar. Dikemudikan Setsuna F. Seiei dan menjadi inti dari pertarungan menghadapi aliansi dunia.', 'https://static.wikia.nocookie.net/gundam/images/9/98/Gn-0000.jpg/revision/latest/scale-to-width-down/381?cb=20201114145012'),
  (25, 'Gundam Barbatos', 'ASW-G-08', 10, 'Mikazuki Augus', 'Tekkadan', 'Gundam Frame', 18, 28.5, array['Mace', 'Lance', '200mm Cannon'], 'Mobile suit berusia ratusan tahun berbasis Gundam Frame dengan dua reaktor Ahab. Gaya bertarungnya brutal dan tanpa banyak senjata, mengandalkan mace berat dan kemampuan Mikazuki.', 'https://static.wikia.nocookie.net/gundam/images/8/8e/ASW-G-08_Gundam_Barbatos_1st_Form_%28Front%29.png/revision/latest?cb=20181007005623'),
  (26, 'Gundam Vidar', 'ASW-G-XX', 10, 'Gaelio Bauduin', 'Gjallarhorn', 'Gundam Frame', null, null, '{}'::text[], 'Mobile frame Gundam Frame milik Gaelio Bauduin dari Gjallarhorn, organisasi yang menguasai keamanan Bumi. Menjadi lawan sepadan Barbatos dan menunjukkan kekuatan teknologi Gjallarhorn.', 'https://static.wikia.nocookie.net/gundam/images/f/f3/Gundam_vidar_front_lineart_color.png/revision/latest/scale-to-width-down/452?cb=20251012031335'),
  (27, 'Gundam Aerial', 'XVX-016', 11, 'Suletta Mercury', 'Asticassia School of Technology', 'Gundam sekolah', null, null, array['Beam Saber', 'Bit Staves'], 'Gundam yang dipakai Suletta Mercury di Asticassia. Dilengkapi Bit Staves yang berfungsi sebagai perisai dan senjata, serta sistem GUND-Format yang menyimpan rahasia besar.', 'https://static.wikia.nocookie.net/gundam/images/3/3d/Gundam_Aerial_Bit_On_Form_Front.png/revision/latest/scale-to-width-down/498?cb=20260809142138'),
  (28, 'Zeong', 'MSN-02', 1, 'Char Aznable', 'Principality of Zeon', 'Newtype khusus', null, null, array['Wired Mega Particle Cannon', 'Mega Particle Cannon'], 'Mobile suit eksperimental Zeon untuk pilot Newtype yang tidak berkaki. Kedua lengannya bisa dilepas dan dikendalikan dari jauh lewat kabel. Dipakai Char dalam pertempuran terakhir di A Baoa Qu.', 'https://static.wikia.nocookie.net/gundam/images/a/a0/Msn-02.jpg/revision/latest/scale-to-width-down/559?cb=20180630123219'),
  (29, 'Gelgoog Commander Type (Char Custom)', 'MS-14S', 1, 'Char Aznable', 'Principality of Zeon', 'Unit komandan', null, null, array['Beam Rifle', 'Beam Naginata', 'Shield'], 'Mobile suit produksi massal Zeon pertama yang dipersenjatai beam, versi komandan berwarna merah milik Char. Senjata khasnya adalah Beam Naginata dengan dua bilah.', 'https://static.wikia.nocookie.net/gundam/images/2/24/MS14S_GelgoogComTypeCharColor_-_Front.jpg/revision/latest/scale-to-width-down/374?cb=20230722100106'),
  (30, 'Gundam Mk-II', 'RX-178', 2, 'Kamille Bidan', 'AEUG', 'Prototipe serbaguna', null, null, array['Beam Rifle', 'Beam Saber', 'Hyper Bazooka', 'Shield'], 'Gundam rancangan Titans yang direbut AEUG di awal cerita. Menjadi unit pertama Kamille Bidan sebelum ia beralih ke Zeta Gundam, lalu dipakai pilot AEUG lain.', 'https://static.wikia.nocookie.net/gundam/images/0/0a/Gundam_Mk-II_%28Titans%29_Front.png/revision/latest/scale-to-width-down/423?cb=20251012211654'),
  (31, 'Master Gundam', 'GF13-001NHII', 7, 'Master Asia (Toho Fuhai)', 'Neo Hong Kong', 'Mobile Fighter', null, null, array['Darkness Finger', 'Master Cloth'], 'Mobile Fighter milik Master Asia, guru sekaligus lawan terbesar Domon Kasshu. Jurus andalannya Darkness Finger, dan kain Master Cloth di punggungnya bisa dipakai menyerang.', 'https://static.wikia.nocookie.net/gundam/images/5/53/GF13-001NHII_Master_Gundam_Attack_Mode_Front.png/revision/latest/scale-to-width-down/515?cb=20251012213149'),
  (32, 'Gundam Heavyarms', 'XXXG-01H', 6, 'Trowa Barton', 'Koloni (Operation Meteor)', 'Artileri berat', null, null, array['Beam Gatling', 'Homing Missile', 'Army Knife'], 'Gundam milik Trowa Barton yang dipenuhi senjata api di seluruh tubuhnya. Unggul dalam serangan jarak menengah dengan tembakan beruntun dalam jumlah besar.', 'https://static.wikia.nocookie.net/gundam/images/e/e6/Heavyarms_Front_%28transparent%29.png/revision/latest/scale-to-width-down/402?cb=20251012024250'),
  (33, 'Gundam Sandrock', 'XXXG-01SR', 6, 'Quatre Raberba Winner', 'Koloni (Operation Meteor)', 'Pertempuran darat', null, null, array['Heat Shotel', 'Beam Submachine Gun', 'Cross Crusher'], 'Gundam milik Quatre Raberba Winner yang tangguh di medan gurun. Bersenjata sepasang pedang melengkung Heat Shotel dan dibantu pasukan Maganac Corps.', 'https://static.wikia.nocookie.net/gundam/images/3/37/Sandrock_Front_%28transparent%29.png/revision/latest/scale-to-width-down/386?cb=20251012024414'),
  (34, 'Shenlong Gundam', 'XXXG-01S', 6, 'Chang Wufei', 'Koloni (Operation Meteor)', 'Jarak dekat', null, null, array['Dragon Hang', 'Beam Glaive', 'Flamethrower'], 'Gundam milik Chang Wufei yang mengandalkan pertarungan jarak dekat. Lengan kanannya, Dragon Hang, bisa memanjang dan menyemburkan api.', 'https://static.wikia.nocookie.net/gundam/images/2/26/Shenlong_Front_%28transparent%29.png/revision/latest/scale-to-width-down/387?cb=20251012024136'),
  (35, 'Gundam Dynames', 'GN-002', 9, 'Lockon Stratos', 'Celestial Being', 'Penembak jitu', null, null, array['GN Sniper Rifle', 'GN Beam Pistol', 'GN Full Shield'], 'Gundam penembak jitu Celestial Being yang dikemudikan Lockon Stratos. Dibantu robot pendamping HARO untuk membidik target dari jarak sangat jauh.', 'https://static.wikia.nocookie.net/gundam/images/4/4c/Gundam_Dynames_%28Front%29_01.png/revision/latest/scale-to-width-down/394?cb=20220717103940'),
  (36, 'Gundam Kyrios', 'GN-003', 9, 'Allelujah Haptism', 'Celestial Being', 'Transformable', null, null, array['GN Submachine Gun', 'GN Beam Saber', 'GN Shield'], 'Gundam Celestial Being yang bisa berubah menjadi mode pesawat untuk serangan cepat dan pengeboman. Dikemudikan Allelujah Haptism.', 'https://static.wikia.nocookie.net/gundam/images/6/6d/GN-003_Kyrios.png/revision/latest/scale-to-width-down/405?cb=20210410171256'),
  (37, 'Gundam Virtue', 'GN-005', 9, 'Tieria Erde', 'Celestial Being', 'Artileri berat', null, null, array['GN Bazooka', 'GN Cannon', 'GN Beam Saber'], 'Gundam berarmor tebal dengan daya tembak besar milik Tieria Erde. Di balik armornya tersembunyi Gundam Nadleeh yang lebih ramping.', 'https://static.wikia.nocookie.net/gundam/images/1/1e/Gundam_Virtue_%28Front%29_01.png/revision/latest/scale-to-width-down/504?cb=20220717105108'),
  (38, 'Gundam Kimaris', 'ASW-G-66', 10, 'Gaelio Bauduin', 'Gjallarhorn', 'Gundam Frame', null, null, array['Gungnir', 'Combat Knife'], 'Gundam Frame warisan keluarga Bauduin yang dikemudikan Gaelio. Unggul dalam kecepatan dan serangan menyerbu dengan tombak raksasa Gungnir.', 'https://static.wikia.nocookie.net/gundam/images/3/35/ASW-G-66_Gundam_Kimaris_%28Front%29.png/revision/latest/scale-to-width-down/452?cb=20251011053831'),
  (39, 'Gundam Calibarn', 'X-EX01', 11, 'Suletta Mercury', 'Asticassia School of Technology', 'Prototipe GUND-Format', null, null, array['Variable Rod Rifle', 'Beam Saber'], 'Prototipe Gundam yang dikemudikan Suletta Mercury di akhir cerita. Sistem GUND-Format-nya sangat membebani tubuh pilot.', 'https://static.wikia.nocookie.net/gundam/images/9/98/Gundam_calibarn_front_lineart_color.png/revision/latest/scale-to-width-down/542?cb=20260809141344'),
  (40, 'Unicorn Gundam 02 Banshee Norn', 'RX-0[N]', 5, 'Riddhe Marcenas', 'Earth Federation', 'Transformable (NT-D)', null, null, array['Beam Magnum', 'Revolving Launcher', 'Beam Saber'], 'Unit kedua Unicorn Gundam yang berwarna hitam dengan psycho-frame keemasan. Versi Norn dikemudikan Riddhe Marcenas yang menjadi rival Banagher.', 'https://static.wikia.nocookie.net/gundam/images/4/48/Banshee_Norn_Unicorn_Mode_front.png/revision/latest/scale-to-width-down/484?cb=20251208040648'),
  (41, 'Gundam NT-1 "Alex"', 'RX-78NT-1', 12, 'Christina Mackenzie', 'Earth Federation', 'Prototipe Newtype', null, null, array['Beam Rifle', 'Beam Saber', 'Gatling Gun (lengan)'], 'Gundam yang dirancang untuk Amuro Ray dengan respons sangat cepat dan lapisan Chobham Armor. Menjadi sasaran operasi Zeon di koloni netral Side 6.', 'https://static.wikia.nocookie.net/gundam/images/1/1a/RX-78NT-1.jpg/revision/latest/scale-to-width-down/375?cb=20201005064825'),
  (42, 'Zaku II Kai', 'MS-06FZ', 12, 'Bernard Wiseman', 'Principality of Zeon', 'Produksi massal', null, null, array['Zaku Machine Gun', 'Heat Hawk', 'Hand Grenade'], 'Versi akhir Zaku II yang disempurnakan di penghujung perang. Dikemudikan Bernie dalam duel putus asa melawan Gundam NT-1.', 'https://static.wikia.nocookie.net/gundam/images/5/5a/Ms-06fz.jpg/revision/latest/scale-to-width-down/406?cb=20201005143847'),
  (43, 'Gundam GP01 Zephyranthes', 'RX-78GP01', 13, 'Kou Uraki', 'Earth Federation', 'Prototipe', null, null, array['Beam Rifle', 'Beam Saber', 'Shield'], 'Prototipe Gundam dari proyek Gundam Development Project. Kemudian dimodifikasi menjadi versi Full Vernian untuk pertempuran di luar angkasa.', 'https://static.wikia.nocookie.net/gundam/images/6/61/Gundam_GP01_Front.png/revision/latest/scale-to-width-down/364?cb=20250208175729'),
  (44, 'Gundam GP02A Physalis', 'RX-78GP02A', 13, 'Anavel Gato', 'Delaz Fleet', 'Penyerang nuklir', null, null, array['Atomic Bazooka', 'Beam Saber', 'Radiator Shield'], 'Gundam yang membawa Atomic Bazooka berhulu ledak nuklir. Dicuri Anavel Gato dari pangkalan Federasi, memicu seluruh cerita 0083.', 'https://static.wikia.nocookie.net/gundam/images/d/d1/Anavel_Gato_Gundam_%22Physalis%22.jpeg/revision/latest/scale-to-width-down/465?cb=20241025063134'),
  (45, 'Gundam F91', 'F91', 14, 'Seabook Arno', 'Earth Federation', 'Mobile suit kecil', null, null, array['VSBR', 'Beam Saber', 'Beam Shield'], 'Mobile suit generasi baru yang berukuran lebih kecil. Saat bekerja pada batas maksimum, ia melepaskan lapisan permukaannya sehingga tampak meninggalkan bayangan dirinya.', 'https://static.wikia.nocookie.net/gundam/images/f/fa/F91_Front_HD.png/revision/latest/scale-to-width-down/394?cb=20240907065228'),
  (46, 'Vigna Ghina', 'XM-07', 14, 'Cecily Fairchild (Berah Ronah)', 'Crossbone Vanguard', 'Unit komandan', null, null, array['Beam Rifle', 'Beam Saber'], 'Mobile suit Crossbone Vanguard yang dikemudikan Cecily Fairchild setelah ia dibawa keluarga Ronah. Memiliki kemampuan Newtype tinggi dan menjadi lawan sekaligus orang terdekat Seabook.', 'https://static.wikia.nocookie.net/gundam/images/4/4e/XM-07_Vigna_Ghina_Front_HD.png/revision/latest/scale-to-width-down/343?cb=20240904084429'),
  (47, 'Victory Gundam', 'LM312V04', 15, 'Uso Ewin', 'League Militaire', 'Combining', null, null, array['Beam Rifle', 'Beam Saber', 'Beam Shield'], 'Gundam modular League Militaire yang tersusun dari tiga bagian (Core Fighter, Top Fighter, Bottom Fighter). Bagian yang rusak mudah diganti, cocok untuk kelompok perlawanan dengan sumber daya terbatas.', 'https://static.wikia.nocookie.net/gundam/images/6/6f/LM312V04_Victory_Gundam_Front.png/revision/latest/scale-to-width-down/412?cb=20200930192835'),
  (48, 'V2 Gundam', 'LM314V21', 15, 'Uso Ewin', 'League Militaire', 'Combining', null, null, array['Beam Rifle', 'Beam Saber', 'Beam Shield', 'Minovsky Drive'], 'Penerus Victory Gundam dengan Minovsky Drive yang memancarkan sayap cahaya (Wings of Light). Sayap itu juga bisa dipakai sebagai senjata.', 'https://static.wikia.nocookie.net/gundam/images/1/10/LM314V21_Victory_2_Gundam.jpg/revision/latest/scale-to-width-down/367?cb=20201006034457'),
  (49, 'Gundam X', 'GX-9900', 16, 'Garrod Ran', 'Freeden', 'Gundam Newtype', null, null, array['Satellite Cannon', 'Beam Sword', 'Shield Buster Rifle'], 'Gundam peninggalan perang yang ditemukan Garrod Ran. Senjata utamanya, Satellite Cannon, ditenagai pancaran gelombang mikro dari Bulan.', 'https://static.wikia.nocookie.net/gundam/images/4/4d/Gx-9900.gif/revision/latest?cb=20091126113856'),
  (50, 'Gundam Virsago', 'NRX-0013', 16, 'Shagia Frost', 'New United Nations Earth', 'Gundam jarak dekat', null, null, array['Mega Sonic Cannon', 'Strike Claw'], 'Gundam milik Shagia Frost, salah satu dari dua bersaudara Frost. Biasanya bertarung bersama Gundam Ashtaron milik adiknya.', 'https://static.wikia.nocookie.net/gundam/images/1/19/Nrx-0013.jpg/revision/latest/scale-to-width-down/423?cb=20201001094811'),
  (51, 'Turn A Gundam', 'WD-M01', 17, 'Loran Cehack', 'Inglessa Militia', 'Mobile suit kuno', null, null, array['Beam Rifle', 'Beam Saber', 'Moonlight Butterfly'], 'Mobile suit kuno berkumis yang ditemukan di dalam patung White Doll. Menyimpan senjata Moonlight Butterfly yang dulu memusnahkan peradaban manusia.', 'https://static.wikia.nocookie.net/gundam/images/8/80/SYSTEM_%E2%88%80-99_%E2%88%80_Gundam_Front.png/revision/latest/scale-to-width-down/389?cb=20261028021532'),
  (52, 'Turn X', 'CONCEPT-X 6-1-2', 17, 'Gym Ghingham', 'Moonrace', 'Mobile suit kuno', null, null, '{}'::text[], 'Mobile suit kuno yang menjadi pasangan sekaligus lawan Turn A Gundam. Tubuhnya bisa terpisah menjadi beberapa bagian yang menyerang sendiri-sendiri.', 'https://static.wikia.nocookie.net/gundam/images/a/a4/CONCEPT-X_6-1-2_Turn_X_-_Front.png/revision/latest/scale-to-width-down/388?cb=20261028021326'),
  (53, 'Destiny Gundam', 'ZGMF-X42S', 18, 'Shinn Asuka', 'ZAFT', 'Serbaguna', null, null, array['Arondight Beam Sword', 'Long-range Beam Cannon', 'Palma Fiocina', 'Beam Boomerang'], 'Gundam milik Shinn Asuka yang menggabungkan kemampuan jarak dekat dan jauh. Sistem pendorongnya meninggalkan bayangan cahaya saat bergerak cepat.', 'https://static.wikia.nocookie.net/gundam/images/7/7a/Destiny_Front_%28Official%29.png/revision/latest/scale-to-width-down/377?cb=20251011053210'),
  (54, 'Strike Freedom Gundam', 'ZGMF-X20A', 18, 'Kira Yamato', 'Clyne Faction', 'Serbaguna', null, null, array['Super DRAGOON', 'Beam Rifle', 'Rail Gun', 'Beam Saber'], 'Penerus Freedom Gundam milik Kira Yamato. Sayapnya membawa delapan DRAGOON yang bisa dilepas dan menembak dari berbagai arah.', 'https://static.wikia.nocookie.net/gundam/images/5/58/Strike_freedom_front_lineart_color.png/revision/latest/scale-to-width-down/463?cb=20260103060837'),
  (55, 'Infinite Justice Gundam', 'ZGMF-X19A', 18, 'Athrun Zala', 'Clyne Faction', 'Jarak dekat', null, null, array['Fatum-01', 'Beam Saber', 'Beam Rifle', 'Griffon Beam Blade'], 'Penerus Justice Gundam milik Athrun Zala. Ransel Fatum-01 bisa dilepas dan dikendalikan terpisah, dan kakinya dilengkapi bilah beam.', 'https://static.wikia.nocookie.net/gundam/images/e/e0/Infinite_justice_front_lineart_color.png/revision/latest/scale-to-width-down/494?cb=20230711013902'),
  (56, 'Gundam AGE-1 Normal', 'AGE-1', 19, 'Flit Asuno', 'Earth Federation', 'Serbaguna', null, null, array['Dodds Rifle', 'Beam Saber'], 'Gundam pertama keluarga Asuno yang dibangun Flit. Sistem AGE menganalisis pertempuran lalu merancang perlengkapan baru (Wear) yang sesuai.', 'https://static.wikia.nocookie.net/gundam/images/c/c2/Age-1.jpg/revision/latest/scale-to-width-down/328?cb=20120123161117'),
  (57, 'Gundam AGE-2 Normal', 'AGE-2', 19, 'Asemu Asuno', 'Earth Federation', 'Transformable', null, null, array['Hyper Dodds Rifle', 'Beam Saber'], 'Gundam generasi kedua milik Asemu Asuno, anak Flit. Bisa berubah menjadi mode pesawat (Stryder Form) untuk bergerak cepat.', 'https://static.wikia.nocookie.net/gundam/images/4/43/Age-2-ms.png/revision/latest/scale-to-width-down/640?cb=20260603134516'),
  (58, 'Build Strike Gundam', 'GAT-X105B', 20, 'Reiji (fighter), Sei Iori (builder)', 'Gunpla Battle', 'Gunpla custom', null, null, array['Beam Rifle', 'Beam Saber', 'Build Booster', 'Shield'], 'Gunpla rakitan Sei Iori berbasis Strike Gundam. Sei merakit dan menyempurnakannya, sedangkan Reiji yang mengendalikannya dalam pertarungan.', 'https://static.wikia.nocookie.net/gundam/images/6/67/Build_Strike_Gundam_-_Front_%28without_full_package%29.png/revision/latest/scale-to-width-down/367?cb=20131211155524'),
  (59, 'Star Build Strike Gundam', 'GAT-X105B/ST', 20, 'Reiji (fighter), Sei Iori (builder)', 'Gunpla Battle', 'Gunpla custom', null, null, array['Universe Booster', 'Absorb Shield', 'Beam Rifle'], 'Peningkatan Build Strike untuk kejuaraan dunia. Mampu menyerap partikel Plavsky lewat perisainya dan memakainya untuk serangan balik.', 'https://static.wikia.nocookie.net/gundam/images/8/8f/GAT-X105BST_Star_Build_Strike_Gundam_-_Front.png/revision/latest?cb=20131124175145'),
  (60, 'Xi Gundam', 'RX-105', 21, 'Hathaway Noa', 'Mafty', 'Mobile suit besar', null, null, array['Beam Rifle', 'Funnel Missile', 'Beam Saber'], 'Gundam berukuran besar milik Hathaway Noa dengan Minovsky Craft yang memungkinkannya terbang di atmosfer tanpa penopang tambahan.', 'https://static.wikia.nocookie.net/gundam/images/1/11/Xi_gundam_anime_front_HQ.png/revision/latest/scale-to-width-down/640?cb=20201112115233'),
  (61, 'Penelope', 'RX-104FF', 21, 'Lane Aim', 'Earth Federation', 'Mobile suit besar', null, null, array['Beam Rifle', 'Funnel Missile'], 'Mobile suit Federasi yang menjadi saudara rancangan Xi Gundam. Dikemudikan Lane Aim, pilot muda Federasi yang memburu Mafty.', 'https://static.wikia.nocookie.net/gundam/images/c/c9/Penelope_anime_front_HQ.png/revision/latest/scale-to-width-down/517?cb=20251208042204'),
  (62, 'Impulse Gundam', 'ZGMF-X56S', 18, 'Shinn Asuka', 'ZAFT', 'Modular (Silhouette)', null, null, array['Beam Rifle', 'Beam Saber', 'Silhouette Pack'], 'Gundam pertama Shinn Asuka di SEED Destiny. Tersusun dari beberapa modul yang bisa digabung di udara, dan perlengkapannya diganti lewat Silhouette Pack sesuai misi.', 'https://static.wikia.nocookie.net/gundam/images/d/da/Impulse_gundam_front_lineart_color.png/revision/latest/scale-to-width-down/306?cb=20251011053046')
